INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (1,'ACTIVE','ana@politinder.test','pbkdf2$600000$aUICX/lpfkA8embW1rf/Ag==$lD0B22vakePM1hcQdKOQKmDty1GbddWdf2Sb9FCUarY=','Me gusta guardar los días en fotos y descubrir cafeterías pequeñas de Quito. Si tu plan incluye caminar sin prisa y una buena conversación, me apunto.','Ana Lucía Cárdenas',DATE_SUB(CURDATE(),INTERVAL 22 YEAR),1,1);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (2,'ACTIVE','luis@politinder.test','pbkdf2$600000$WxeUdHD4F2KiZSkVo6XCDw==$/kZIVhANhqtiOPz1+D/r2Rde9v2PJIXy0zQDS7VfA5I=','Entre clases, una partida de básquet y proyectos que casi siempre terminan con café. Recomiéndame una canción y te comparto mi playlist para programar.','Luis Andrés Benavides',DATE_SUB(CURDATE(),INTERVAL 23 YEAR),2,1);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (3,'ACTIVE','sofia@politinder.test','pbkdf2$600000$6mCHh6kXsYaXeTZO/RReYQ==$H4K+KAw8BEgCMHSFhDL1Yatj2/e+R68A0loQdDTMXE4=','Leo de todo un poco y siempre llevo una libreta para dibujar. Mi plan ideal: museo, helado y una conversación que haga olvidar la hora.','Sofía Isabel Montalvo',DATE_SUB(CURDATE(),INTERVAL 21 YEAR),1,5);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (4,'ACTIVE','mateo@politinder.test','pbkdf2$600000$0oJ1/CnmyjnQf8f6nf03+A==$ZY7/pkBYOgcbVfb2X48ZSdNEDGyAYcg/6PXR4gwt+l4=','Los fines de semana cambio los apuntes por una caminata. Estoy aprendiendo a cocinar; mi especialidad, por ahora, es invitar a probar el resultado.','Mateo Alejandro Jaramillo',DATE_SUB(CURDATE(),INTERVAL 24 YEAR),2,9);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (5,'ACTIVE','valentina@politinder.test','pbkdf2$600000$08swPQ7DvQomsCEWySqaKw==$QFzroVYM2ux5FcvPpam0xRfW85IrrTMH3y93ly1mlAE=','Fan de la música en vivo y de los atardeceres desde Guápulo. Busco alguien con curiosidad, sentido del humor y ganas de conocer rincones nuevos.','Valentina Paz Cevallos',DATE_SUB(CURDATE(),INTERVAL 20 YEAR),1,2);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (6,'ACTIVE','diego@politinder.test','pbkdf2$600000$TG6wlwvTSamrQYVqw9kItw==$WzpvIcqEopc7SmcvCH5CcbSt/JyrWz6Cic1vN7IeB+M=','Me gustan las bicicletas, los documentales y arreglar cosas que todavía tienen solución. Un paseo por el parque y un café suenan como un buen comienzo.','Diego Sebastián Aguirre',DATE_SUB(CURDATE(),INTERVAL 25 YEAR),2,10);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (7,'ACTIVE','camila@politinder.test','pbkdf2$600000$OsyEyhuSnAm298CPE4Wfgg==$/6MUWmueZjbZxfdgFhDDCGSof7fl6f5PU+AOYhaDv8k=','Me río fácil, cocino con música y nunca digo que no a un paseo improvisado. Si conoces un buen lugar para desayunar después de clases, tenemos plan.','Camila Fernanda Caicedo',DATE_SUB(CURDATE(),INTERVAL 23 YEAR),1,13);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (8,'ACTIVE','nicolas@politinder.test','pbkdf2$600000$h2eOnfzLJE7FQvG8M76+5w==$2pe2Wxg0GvyjnBEB6yzuMnFenaM/dCHY6FjicipzW1U=','Disfruto las películas que dejan tema de conversación y las escapadas a la montaña. También soy feliz con un juego de mesa y buena compañía.','Nicolás Esteban Chiriboga',DATE_SUB(CURDATE(),INTERVAL 26 YEAR),2,16);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (9,'ACTIVE','isabella@politinder.test','pbkdf2$600000$DH8GuiL41V9pz2WtibKOwQ==$azOzHKtrA3lh1Mpo+2Z0UNU4g/S74DpKPD2I78vHq08=','Me encanta bailar, probar recetas y encontrar pequeñas librerías. Estoy aquí para conocer a alguien con quien los planes sencillos se vuelvan memorables.','Isabella María Naranjo',DATE_SUB(CURDATE(),INTERVAL 22 YEAR),1,18);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (10,'ACTIVE','daniel@politinder.test','pbkdf2$600000$qj4cbQ5kJEZg7hccpz2pvQ==$3iivhual02ER4/7Ufc6FLC4hZpyLDNaL9H0VjAY0DjA=','Entre libros, fotografía urbana y proyectos de la Poli. Prefiero una charla tranquila a los mensajes eternos; podemos empezar por un café.','Daniel Andrés Endara',DATE_SUB(CURDATE(),INTERVAL 24 YEAR),2,21);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (11,'ACTIVE','lucia@politinder.test','pbkdf2$600000$3UFbclDTMQcO3yo9S+b9Bw==$zNIYYKFaefMrZJHPcLiy07fAEUCGNVYky+dnKvvFrvQ=','Los domingos son para caminar, sacar fotos y buscar algo rico que comer. Me gusta la gente que escucha y se entusiasma contando lo que le apasiona.','Lucía Belén Santillán',DATE_SUB(CURDATE(),INTERVAL 21 YEAR),1,22);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (12,'ACTIVE','emilia@politinder.test','pbkdf2$600000$ndn6i8NfFx93UwBzPy80yA==$jvFM2VHT5ZLTSGBLY3eEseqxQsFWMI/b6vi0+bpaI48=','Colecciono canciones, plantas pequeñas y ganas de viajar. Siempre tengo una recomendación de película y espacio para descubrir una nueva contigo.','Emilia Josefina Viteri',DATE_SUB(CURDATE(),INTERVAL 20 YEAR),1,1);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (13,'ACTIVE','joaquin@politinder.test','pbkdf2$600000$TEQLE2qBJMFD7I4fbvl1uQ==$4j0k+Lx6n3hshCban7nRCkg0CsUbQejnlPJ2bgWfdjE=','Juego fútbol, improviso en la guitarra y disfruto los paseos largos. Me gustan las conversaciones honestas y quienes no se toman demasiado en serio.','Joaquín Andrés Cordero',DATE_SUB(CURDATE(),INTERVAL 25 YEAR),2,4);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (14,'ACTIVE','martina@politinder.test','pbkdf2$600000$Ns2zOhDKEB1U3xANJ09ROw==$5v/f1nd97gjOxu3EFRyY/L75fGMjSJ+2u0HqkTqCgWM=','Me pierdo feliz entre libros y exposiciones. Aprendo a hacer cerámica y busco compañía para descubrir sitios bonitos cerca de la universidad.','Martina Isabel Salazar',DATE_SUB(CURDATE(),INTERVAL 23 YEAR),1,7);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (15,'ACTIVE','gabriel@politinder.test','pbkdf2$600000$piiLxWjTfkYynrtUKt9LWg==$zBmOVV6YoqgcyNRD0yjdqgTqqxR+0M6wyNRjGiw7ZvY=','Me recarga nadar, escuchar jazz y pasar tiempo al aire libre. Me interesa conocer a alguien con quien compartir metas, risas y una buena sobremesa.','Gabriel Alejandro Villamar',DATE_SUB(CURDATE(),INTERVAL 27 YEAR),2,14);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (16,'ACTIVE','renata@politinder.test','pbkdf2$600000$QzsI5ZerWMyWCKRRlOHP+A==$+4h8i9lgxuq92c+sJa+SbqBBXIjPbaFQDzs021e7Egg=','Me gusta bailar salsa, cocinar para mis amigos y ver la ciudad desde otro ángulo. Hagamos un plan sencillo y dejemos que la conversación lo mejore.','Renata Victoria Palacios',DATE_SUB(CURDATE(),INTERVAL 24 YEAR),1,20);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (17,'PAUSED','andres@politinder.test','pbkdf2$600000$eKn0ullBqutIVzxHQ3YbeQ==$L9qODKePNNknIkDrDltiWSaTpAUaJRlBYTmvTA6huTo=','Curioso por naturaleza: tecnología, senderos y recetas nuevas. Valoro la calma, el humor y la gente que cumple lo que promete.','Andrés Felipe Alvarado',DATE_SUB(CURDATE(),INTERVAL 33 YEAR),2,22);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (18,'PAUSED','elena@politinder.test','pbkdf2$600000$OU6Ou5XIF2VbYPxOPl7vmQ==$N8XtHnII8zidin9ttU+R1dGHVWnDi6oONLRnMVUnLfE=','Disfruto la fotografía, el cine latinoamericano y las caminatas de domingo. Un encuentro con buena conversación vale más que un plan perfecto.','Elena Cristina Echeverría',DATE_SUB(CURDATE(),INTERVAL 33 YEAR),1,24);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (19,'ACTIVE','paula@politinder.test','pbkdf2$600000$xpBymLMKzJXjjiUtpCcNLA==$qAEYLhUPG5wTwG90kWBkS4hno1P906+iOvANDuKcT5k=','Estoy aprendiendo guitarra y buscando mi cafetería favorita de Quito. Me gustan los perros, las películas de misterio y los planes espontáneos.','Paula Daniela Ponce',DATE_SUB(CURDATE(),INTERVAL 19 YEAR),1,1);
INSERT INTO `USER` (idUser,status,mail,password,biography,name,bornDate,idGender,idMajor) VALUES (20,'ACTIVE','samuel@politinder.test','pbkdf2$600000$qVso9GZrDfDCMkmCkvb+zQ==$8nx2W9qrLrnDbDDNLoAFlWOVuWtJLOPbJ2IRXKCZ5GQ=','Fan del básquet, los videojuegos cooperativos y los viajes cortos. Si te ríes de los chistes malos, probablemente nos llevemos muy bien.','Samuel David Zambrano',DATE_SUB(CURDATE(),INTERVAL 22 YEAR),2,2);
